const debris = scene.tiles.find(
  tile => tile.name === "ground-floor-balcony-debris"
);

if (debris)
{
  await debris.update({ hidden: false });
}


const region = canvas.scene.regions.find(r => r.name === "Under Balcony");

if (region) {
  for (const behavior of region.behaviors) {
    if (!behavior.disabled) {
      await behavior.update({ disabled: true });
    }
  }
}

